-- Run after the candidate migration and preview seeds INSIDE a rollback transaction.
-- Never run against real learner records; every user below is a transaction-local fixture.
create temp table loop_test_users (owner_id uuid, other_id uuid);
insert into loop_test_users values(gen_random_uuid(),gen_random_uuid());
insert into auth.users(id,email) select owner_id,'qa-loop-'||owner_id||'@example.invalid' from loop_test_users union all select other_id,'qa-loop-'||other_id||'@example.invalid' from loop_test_users;
create temp table loop_test_evidence (test text primary key);
do $$
declare u uuid; other_u uuid; req uuid:=gen_random_uuid(); sid uuid; q public.quiz_questions; futureq public.quiz_questions; c public.source_checked_content_versions; result jsonb; repeated jsonb; retry jsonb; queue_id uuid; review jsonb; bad text; denied boolean; before_score int;
begin
 select owner_id,other_id into u,other_u from loop_test_users;
 result:=public.start_source_checked_session(u,req,2,null,null,'preview'); sid:=(result->'session'->>'id')::uuid;
 repeated:=public.start_source_checked_session(u,req,2,null,null,'preview');
 assert result=repeated,'start request not idempotent';
 insert into loop_test_evidence values('idempotent session start');
 select * into q from public.quiz_questions where session_id=sid and question_index=0;
 select * into futureq from public.quiz_questions where session_id=sid and question_index=1;
 select * into c from public.source_checked_content_versions where id=q.source_checked_content_id;
 denied:=false; begin perform public.present_source_checked_question(u,futureq.id,'preview'); exception when others then denied:=true; end; assert denied,'future question was exposed';
 denied:=false; begin perform public.answer_source_checked_question(u,q.id,'A','preview'); exception when others then denied:=true; end; assert denied,'unpresented question was answered';
 denied:=false; begin perform public.present_source_checked_question(other_u,q.id,'preview'); exception when others then denied:=true; end; assert denied,'other user read question';
 denied:=false; begin perform public.present_source_checked_question(u,q.id,'production'); exception when others then denied:=true; end; assert denied,'preview leaked to production';
 insert into loop_test_evidence values('current-question exposure, ownership and audience checks');
 result:=public.present_source_checked_question(u,q.id,'preview'); assert not (result ? 'correct_answer'),'key leaked in question';
 bad:=case when q.correct_answer='A' then 'B' else 'A' end;
 result:=public.answer_source_checked_question(u,q.id,bad,'preview');
 repeated:=public.answer_source_checked_question(u,q.id,q.correct_answer,'preview');
 assert result=repeated and (result->>'score')::int=0 and (result->>'total_answered')::int=1,'answer not idempotent';
 select id into queue_id from public.source_checked_review_queue where source_question_id=q.id;
 assert queue_id is not null,'miss did not schedule';
 assert (select due_at-missed_at=interval '1 day' from public.source_checked_review_queue where id=queue_id),'wrong review delay';
 insert into loop_test_evidence values('first answer final, exact original score, 24-hour miss scheduling');
 denied:=false; begin perform public.start_source_checked_review(u,queue_id,'preview'); exception when others then denied:=true; end; assert denied,'early review allowed';
 denied:=false; begin perform public.answer_source_checked_question(other_u,q.id,'A','preview'); exception when others then denied:=true; end; assert denied,'other user answered question';
 retry:=public.start_source_checked_retry(u,q.id,'preview');
 repeated:=public.start_source_checked_retry(u,q.id,'preview'); assert retry=repeated,'retry duplicated';
 assert retry->'question'->>'question_stem'=c.packet->'retry'->>'question_stem','wrong retry variant';
 result:=public.answer_source_checked_question(u,(retry->'question'->>'id')::uuid,c.packet->'retry'->>'correct_answer','preview');
 assert (result->>'score')::int=1,'retry incorrect score';
 assert (select score=0 and current_question_index=1 from public.quiz_sessions where id=sid),'retry changed original';
 insert into loop_test_evidence values('retry uses fresh family variant, resumes, scores separately');
 perform public.present_source_checked_question(u,futureq.id,'preview');
 result:=public.answer_source_checked_question(u,futureq.id,futureq.correct_answer,'preview');
 assert (result->>'session_complete')::boolean and (result->>'score')::int=1,'original completion wrong';
 assert (select count(*)=1 from public.source_checked_review_queue where user_id=u),'correct original scheduled review';
 insert into loop_test_evidence values('original completion, correct answer creates no review');
 update public.source_checked_review_queue set missed_at=now()-interval '2 days',due_at=now()-interval '1 day' where id=queue_id;
 denied:=false; begin perform public.start_source_checked_review(other_u,queue_id,'preview'); exception when others then denied:=true; end; assert denied,'other user started review';
 review:=public.start_source_checked_review(u,queue_id,'preview'); repeated:=public.start_source_checked_review(u,queue_id,'preview'); assert review=repeated,'review did not resume';
 assert review->'question'->>'question_stem'=c.packet->'reviews'->0->>'question_stem','wrong delayed variant';
 denied:=false; begin perform public.answer_source_checked_review(other_u,(review->'question'->>'id')::uuid,'A','preview'); exception when others then denied:=true; end; assert denied,'other user answered review';
 result:=public.answer_source_checked_review(u,(review->'question'->>'id')::uuid,c.packet->'reviews'->0->>'correct_answer','preview');
 repeated:=public.answer_source_checked_review(u,(review->'question'->>'id')::uuid,'A','preview'); assert result=repeated,'review answer changed';
 assert (result->>'correct')::boolean and (result->>'exhausted')::boolean,'review not completed';
 assert (select score=1 from public.quiz_sessions where id=sid),'review changed original score';
 denied:=false; begin perform public.start_source_checked_review(u,queue_id,'preview'); exception when others then denied:=true; end; assert denied,'delayed variant recycled';
 assert (public.source_checked_review_status(u,'preview')->>'exhausted_count')::int=1,'exhaustion missing';
 assert jsonb_array_length(public.source_checked_review_status(u,'preview')->'due')=0,'exhausted review still due';
 insert into loop_test_evidence values('delayed review resumes, ownership, first-answer final, exhaustion, separate scores');
 -- Mark every remaining original seen to verify exhaustion cannot generate fallback.
 insert into public.source_checked_exposures(user_id,packet_id,role) select u,packet_id,'original' from public.source_checked_content_versions where audience='preview' on conflict do nothing;
 denied:=false; begin perform public.start_source_checked_session(u,gen_random_uuid(),5,null,null,'preview'); exception when others then denied:=sqlerrm like '%No fresh%'; end; assert denied,'exhausted bank did not stop';
 insert into loop_test_evidence values('bank exhaustion stops instead of repeating or generating');
 denied:=false; begin update public.source_checked_content_versions set packet=jsonb_set(packet,'{focus}','"changed"') where id=c.id; exception when others then denied:=true; end; assert denied,'published content mutable';
 update public.source_checked_content_versions set withdrawn_at=now(),withdrawal_reason='transaction-only QA withdrawal' where id=c.id;
 denied:=false; begin perform public.answer_source_checked_question(u,q.id,bad,'preview'); exception when others then denied:=true; end; assert denied,'withdrawn answer replay allowed';
 denied:=false; begin perform public.start_source_checked_retry(u,q.id,'preview'); exception when others then denied:=true; end; assert denied,'withdrawn retry allowed';
 denied:=false; begin perform public.answer_source_checked_review(u,(review->'question'->>'id')::uuid,'A','preview'); exception when others then denied:=true; end; assert denied,'withdrawn review feedback allowed';
 denied:=false; begin update public.source_checked_content_versions set withdrawn_at=null where id=c.id; exception when others then denied:=true; end; assert denied,'withdrawal reversed';
 insert into loop_test_evidence values('immutable publication and irreversible withdrawal across all scoring paths');
 assert not has_function_privilege('authenticated','public.start_source_checked_session(uuid,uuid,integer,text,text,text)','execute'),'client can invoke service RPC';
 assert not has_table_privilege('authenticated','public.source_checked_content_versions','select'),'client can read full bank';
 assert not has_table_privilege('authenticated','public.source_checked_review_attempts','insert'),'client can fabricate review';
 insert into loop_test_evidence values('service-only mutation and bank permissions');
end $$;
select set_config('request.jwt.claim.sub',(select other_id::text from loop_test_users),true);
set local role authenticated;
do $$ begin
 assert (select count(*)=0 from public.source_checked_review_queue),'RLS queue leak';
 assert (select count(*)=0 from public.source_checked_review_attempts),'RLS attempts leak';
 assert (select count(*)=0 from public.source_checked_exposures),'RLS exposures leak';
end $$;
reset role;
insert into loop_test_evidence values('cross-user RLS hides queue, attempts and exposure history');
select jsonb_agg(test order by test) as passed from loop_test_evidence;
select set_config('request.jwt.claim.sub',(select owner_id::text from loop_test_users),true);
set local role authenticated;
do $$
declare denied boolean; s uuid; q uuid;
begin
 select id into s from public.quiz_sessions where content_policy='source_checked_v1' limit 1;
 select id into q from public.quiz_questions where session_id=s limit 1;
 assert s is not null and q is not null,'fixture not visible to owner';
 denied:=false; begin update public.quiz_sessions set score=99 where id=s; exception when others then denied:=true; end; assert denied,'owner changed score';
 denied:=false; begin update public.quiz_questions set is_correct=true where id=q; exception when others then denied:=true; end; assert denied,'owner changed answer';
 denied:=false; begin delete from public.quiz_questions where id=q; exception when others then denied:=true; end; assert (select count(*)=1 from public.quiz_questions where id=q),'owner deleted frozen question';
 denied:=false; begin delete from public.quiz_sessions where id=s; exception when others then denied:=true; end; assert (select count(*)=1 from public.quiz_sessions where id=s),'owner deleted source session';
 denied:=false; begin insert into public.quiz_questions(session_id,question_index,question_stem,options,correct_answer,rationale_correct,rationale_incorrect,nclex_category,difficulty) values(s,99,'fake','[]','A','fake','{}','Management of Care',2); exception when others then denied:=true; end; assert denied,'owner inserted generated fallback into frozen session';
end $$;
reset role;
insert into loop_test_evidence values('owner cannot mutate scores, answers, frozen membership or delete saved records');
select jsonb_agg(test order by test) as passed from loop_test_evidence;
